output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in one-cell-wide shelf aisles, which explains why the agent leaves the cart before entering the narrow top aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A cart must not be pushed into a single-file shelf aisle from a wider aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "hands_free_pickup_in_single_file_aisle",
    "text": "Items in single-file shelf aisles should be picked up by hand rather than while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_at_wide_aisle_mouths",
    "text": "A cart may only be set down at a wide aisle mouth or other designated cart-staging location.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "topSideAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartStation": "at(1,7)",
        "authorizedCartStagingCell": {
          "or": [
            "topSideAisleMouth",
            "entranceCartStation"
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "authorizedCartStagingCell"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_hand_pickup",
    "text": "After collecting an item by hand inside a single-file shelf aisle, the shopper must return to the parked cart before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "topSideAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "handPickupInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtAisleMouth": {
          "pre": {
            "and": [
              "topSideAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "handPickupInSingleFileAisle",
      "discharge": "retrieveCartAtAisleMouth"
    }
  },
  {
    "id": "no_cartless_walking_except_side_aisle_excursion",
    "text": "Walking without the cart is forbidden except within a narrow side-aisle excursion and its aisle-mouth staging cell.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "topSideAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessExcursionZone": {
          "or": [
            "singleFileShelfAisle",
            "topSideAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessExcursionZone"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_from_entrance",
    "text": "At the start of a shopping trip, the shopper is obliged to take a cart from the entrance area before continuing.",
    "abstraction": {
      "state_properties": {
        "entranceCartStation": "at(1,7)"
      },
      "events": {
        "takeEntranceCart": {
          "pre": {
            "and": [
              "entranceCartStation",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeEntranceCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The shopper must not leave the store without the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
